/*
ReThreads SQL Server installation. Run this ENTIRE file in SSMS or sqlcmd.
No SQLCMD mode or EF CLI needed. Requires SQL Server 2017+ (validated on SQL Server 2022).
Use the SAME @DatabaseName in both files. Default: ReThreadsDb.
Fresh database installation only. No DROP DATABASE, TRUNCATE or existing-data reset.
Current project migration: 20260922115216_AddMonthlyFundStatements.
STEP 2 OF 2: SEED INITIAL DATA.
Run only AFTER 01_ReThreads_Create_Database.sql.
Seeds 8 roles; 5 verified accounts; 1 warehouse; 6 areas; 9 rows; 36 storage positions;
43 categories including grades A/B/C; 4 inspection questions / 12 answers;
weighted thresholds A>=85 / B>=50 / C<50; AI prompt; 10 donation points/kg;
59 EF migration history entries; 30-day schedule and teams from installation date (Vietnam time).
No donation orders, inventory balances, deliveries or fund transactions are inserted.
Rerunning after success DOES NOT reset passwords or overwrite user-edited configuration.

All five accounts use the exact password ReThread@2026 (no backslash):
  manager.demo           Manager
  receiving.staff        ReceivingStaff - pickup
  receiving.warehouse    ReceivingStaff - warehouse drop-off
  classification.staff   ClassificationStaff
  warehouse.staff        WarehouseStaff
Passwords are stored as BCrypt hashes. Staff are assigned to the initial warehouse.
The warehouse's initial map coordinates are approximate and editable by Manager.

After both scripts, configure the backend connection string, for example:
Server=localhost;Database=ReThreadsDb;Trusted_Connection=True;TrustServerCertificate=True
External-service credentials (SMTP, Gemini, GHN, Geoapify, Supabase, PayOS) must be
configured separately in the backend/frontend/mobile environment as appropriate.

*/
USE [master];
SET ANSI_NULLS ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET QUOTED_IDENTIFIER ON;
SET NUMERIC_ROUNDABORT OFF;
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @DatabaseName sysname = N'ReThreadsDb';
IF @DatabaseName IS NULL OR LEN(LTRIM(RTRIM(@DatabaseName)))=0
    THROW 51002, 'Database name is required.', 1;
IF @DatabaseName IN (N'master',N'model',N'msdb',N'tempdb')
    THROW 51003, 'Choose an application database name.', 1;
IF DB_ID(@DatabaseName) IS NULL THROW 51004, 'Run 01_ReThreads_Create_Database.sql first.', 1;

DECLARE @Sql nvarchar(max)=N'USE '+QUOTENAME(@DatabaseName)+N';'+
N'SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @LockResult int;
    EXEC @LockResult=sys.sp_getapplock @Resource=N''ReThreads.Bootstrap'',
        @LockMode=''Exclusive'',@LockOwner=''Transaction'',@LockTimeout=10000;
    IF @LockResult<0 THROW 51000, ''Another database installer is running.'', 1;
IF NOT EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N''ReThreads.Schema.Version'' AND CONVERT(nvarchar(100),value)=N''20260924.2'')
    THROW 51005, ''This database was not initialized by 01_ReThreads_Create_Database.sql. Use a new database and run file 01 first.'', 1;
IF EXISTS(SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N''ReThreads.Seed.Version'' AND CONVERT(nvarchar(100),value)=N''20260924.2'')
BEGIN
    PRINT N''Seed already completed. Existing accounts, passwords and business data were left unchanged.'';
    COMMIT; RETURN;
END;
-- Require all tables to be empty before the first seed; no partial merges or resets.
DECLARE @CheckSql nvarchar(max);
SELECT @CheckSql=STRING_AGG(CAST(N''IF EXISTS(SELECT 1 FROM ''+QUOTENAME(SCHEMA_NAME(schema_id))+N''.''+QUOTENAME(name)+N'') THROW 51006, ''''Database already contains data; first seed requires empty tables.'''', 1;'' AS nvarchar(max)),CHAR(10))
FROM sys.tables WHERE is_ms_shipped=0;
EXEC sys.sp_executesql @CheckSql;
