EXEC sys.sp_executesql N''DECLARE @Now datetime2=SYSUTCDATETIME();
DECLARE @LocalNow datetime2=DATEADD(HOUR,7,@Now);
DECLARE @WarehouseId uniqueidentifier=''''B17468FF-CBE1-46A0-8375-890B50CD2F99'''';
DECLARE @StartDate date = CAST(@LocalNow AS date);
DECLARE @EndDate date = DATEADD(DAY,29,@StartDate);
INSERT INTO WorkScheduleTemplates
    (Id, WarehouseId, Year, WorkingDays, MorningStartTime, MorningEndTime,
     AfternoonStartTime, AfternoonEndTime, CreateAt, IsActive)
SELECT NEWID(), @WarehouseId, y.Year, ''''0,1,2,3,4,5,6'''',
    ''''08:00:00'''', ''''11:00:00'''', ''''13:00:00'''', ''''17:00:00'''', @Now, 1
FROM (SELECT YEAR(@StartDate) Year UNION SELECT YEAR(@EndDate)) y
WHERE NOT EXISTS (SELECT 1 FROM WorkScheduleTemplates t
    WHERE t.WarehouseId = @WarehouseId AND t.Year = y.Year);

;WITH Days AS (
    SELECT @StartDate DayValue
    UNION ALL SELECT DATEADD(DAY,1,DayValue) FROM Days WHERE DayValue < @EndDate
)
INSERT INTO Shifts
    (Id, WarehouseId, ShiftName, ShiftDate, StartTime, EndTime, Status, CreateAt, IsActive)
SELECT NEWID(), @WarehouseId, s.Name, d.DayValue, s.Starts, s.Ends,
    ''''Scheduled'''', @Now, 1
FROM Days d CROSS JOIN (VALUES
    (N''''Ca sáng'''', CAST(''''08:00'''' AS time), CAST(''''11:00'''' AS time)),
    (N''''Ca chiều'''', CAST(''''13:00'''' AS time), CAST(''''17:00'''' AS time))
) s(Name,Starts,Ends)
WHERE DATEADD(SECOND, DATEDIFF(SECOND,CAST(''''00:00'''' AS time),s.Ends),CAST(d.DayValue AS datetime2)) > @LocalNow;

INSERT INTO OperationalTeams
    (Id, ShiftId, TeamType, TeamName, Status, CreateAt, IsActive)
SELECT NEWID(), s.Id, t.Type, t.Name, ''''Scheduled'''', @Now, 1
FROM Shifts s CROSS JOIN (VALUES
    (''''ReceivingPickup'''', N''''Đội nhận đồ tận nơi''''),
    (''''ReceivingWarehouse'''', N''''Đội tiếp nhận tại kho''''),
    (''''Classification'''', N''''Đội phân loại'''')
) t(Type,Name)
WHERE s.WarehouseId = @WarehouseId AND s.IsActive = 1;

INSERT INTO TeamMembers (Id,TeamId,StaffId,CreateAt,IsActive)
SELECT NEWID(),t.Id,u.Id,@Now,1
FROM OperationalTeams t JOIN Shifts s ON s.Id=t.ShiftId
JOIN Users u ON u.UserName = CASE t.TeamType
    WHEN ''''ReceivingPickup'''' THEN ''''receiving.staff''''
    WHEN ''''ReceivingWarehouse'''' THEN ''''receiving.warehouse''''
    WHEN ''''Classification'''' THEN ''''classification.staff'''' END
WHERE s.WarehouseId = @WarehouseId;

-- Verify essential bootstrap invariants before committing the whole install.
IF (SELECT COUNT(*) FROM Roles) <> 8 THROW 51010, ''''Expected all 8 application roles.'''', 1;
IF (SELECT COUNT(*) FROM Users) <> 5 THROW 51011, ''''Expected 5 bootstrap accounts.'''', 1;
IF (SELECT COUNT(*) FROM Categories) <> 43 THROW 51012, ''''Category catalog is incomplete.'''', 1;
IF (SELECT COUNT(*) FROM Categories WHERE Type=''''ConditionGrade'''' AND Code IN (''''GRADE_A'''',''''GRADE_B'''',''''GRADE_C'''')) <> 3
    THROW 51013, ''''Missing A/B/C labels.'''', 1;
IF (SELECT COUNT(*) FROM ConditionQuestions) <> 4 OR (SELECT COUNT(*) FROM ConditionAnswers) <> 12
    THROW 51014, ''''Inspection criteria are incomplete.'''', 1;
IF EXISTS (SELECT 1 FROM Users u JOIN Roles r ON r.Id=u.RoleId
    WHERE r.RoleName LIKE ''''%Staff'''' AND (u.WarehouseId IS NULL OR u.EmailConfirmed=0 OR u.IsActive<>1))
    THROW 51015, ''''Staff account is not ready.'''', 1;
IF EXISTS (SELECT 1 FROM AreaGroups g WHERE NOT EXISTS
    (SELECT 1 FROM StorageLocations l WHERE l.AreaGroupId=g.Id))
    THROW 51016, ''''A storage row has no locations.'''', 1;
IF EXISTS (SELECT 1 FROM Warehouses w WHERE w.TotalCapacityKg <
    (SELECT SUM(a.CapacityKg) FROM WarehouseAreas a WHERE a.WarehouseId=w.Id AND a.IsActive=1))
    THROW 51017, ''''Warehouse capacity is overallocated.'''', 1;
IF EXISTS (SELECT 1 FROM WarehouseAreas a WHERE a.CapacityKg <
    (SELECT SUM(g.CapacityKg) FROM AreaGroups g WHERE g.AreaId=a.Id AND g.IsActive=1))
    THROW 51018, ''''Area capacity is overallocated.'''', 1;
IF EXISTS (SELECT 1 FROM AreaGroups g WHERE g.CapacityKg <
    (SELECT SUM(l.CapacityKg) FROM StorageLocations l WHERE l.AreaGroupId=g.Id AND l.IsActive=1))
    THROW 51019, ''''Row capacity is overallocated.'''', 1;
'';
EXEC sys.sp_addextendedproperty @name=N''ReThreads.Seed.Version'',@value=N''20260924.2'';
PRINT N''Seed completed. Manager/staff accounts and initial configuration are ready.'';

    COMMIT;
END TRY
BEGIN CATCH
    IF XACT_STATE()<>0 ROLLBACK;
    THROW;
END CATCH;
';
EXEC sys.sp_executesql @Sql;
